using System;
using System.Collections.Generic;
using System.IO;
using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using FastOrangeCombined;
class BridgeHarness {
 static int checks; static string lastRequest; static int httpPort, echoPort; static TcpListener http, echo;
 static void Check(bool condition, string name) { if (!condition) throw new Exception("FAIL " + name); checks++; Console.WriteLine("PASS " + name); }
 static byte[] Header(NetworkStream stream) { List<byte> b = new List<byte>(); while (true) { int x = stream.ReadByte(); if(x < 0) throw new EndOfStreamException(); b.Add((byte)x); int n=b.Count; if(n>=4&&b[n-4]==13&&b[n-3]==10&&b[n-2]==13&&b[n-1]==10) return b.ToArray(); if(n>65536) throw new Exception("oversized"); } }
 static string Call(int proxy, string req) { using(TcpClient c=new TcpClient("127.0.0.1",proxy)) { c.ReceiveTimeout=6000; byte[] b=Encoding.ASCII.GetBytes(req); NetworkStream s=c.GetStream(); s.Write(b,0,b.Length); MemoryStream m=new MemoryStream(); b=new byte[4096]; int n; while((n=s.Read(b,0,b.Length))>0)m.Write(b,0,n); return Encoding.ASCII.GetString(m.ToArray()); } }
 static void HttpAccept(IAsyncResult ar) { TcpClient c; try { c=http.EndAcceptTcpClient(ar); http.BeginAcceptTcpClient(HttpAccept,null); } catch{return;} Task.Factory.StartNew(delegate { using(c){ try{ c.ReceiveTimeout=6000; NetworkStream s=c.GetStream(); string h=Encoding.ASCII.GetString(Header(s)); StringBuilder all=new StringBuilder(h); if(h.Contains("Transfer-Encoding: chunked")){ string line; do { line=""; int ch; while((ch=s.ReadByte())>=0){line+=(char)ch; if(line.EndsWith("\r\n"))break;} all.Append(line); }while(!all.ToString().EndsWith("0\r\nX-Test: yes\r\n\r\n")); } else { int idx=h.IndexOf("Content-Length: "); if(idx>=0){ int end=h.IndexOf("\r\n",idx); int len=Int32.Parse(h.Substring(idx+16,end-idx-16)); byte[] body=new byte[len]; int got=0; while(got<len)got+=s.Read(body,got,len-got); all.Append(Encoding.ASCII.GetString(body)); } } lastRequest=all.ToString(); byte[] response=Encoding.ASCII.GetBytes(h.StartsWith("GET /denied")?"HTTP/1.1 403 Forbidden\r\nContent-Length: 4\r\nConnection: close\r\n\r\nNOPE":"HTTP/1.1 200 OK\r\nContent-Length: 4\r\nConnection: close\r\n\r\nPASS"); s.Write(response,0,response.Length); }catch(Exception x){Console.WriteLine("server "+x.Message);} } }); }
 static void EchoAccept(IAsyncResult ar) { TcpClient c; try { c=echo.EndAcceptTcpClient(ar); echo.BeginAcceptTcpClient(EchoAccept,null); }catch{return;} Task.Factory.StartNew(delegate{using(c){try{c.ReceiveTimeout=6000; NetworkStream s=c.GetStream(); byte[] b=new byte[16384]; int n;while((n=s.Read(b,0,b.Length))>0)s.Write(b,0,n);}catch{}}}); }
 static void Tunnel(int port,int num) { using(TcpClient c=new TcpClient("127.0.0.1",port)) { c.ReceiveTimeout=6000; NetworkStream s=c.GetStream(); byte[] h=Encoding.ASCII.GetBytes("CONNECT 127.0.0.1:"+echoPort+" HTTP/1.1\r\nHost: 127.0.0.1\r\n\r\n"); s.Write(h,0,h.Length); string ack=Encoding.ASCII.GetString(Header(s)); if(!ack.StartsWith("HTTP/1.1 200"))throw new Exception(ack); byte[] bytes=new byte[4096]; for(int i=0;i<bytes.Length;i++)bytes[i]=(byte)(i+num); s.Write(bytes,0,bytes.Length); byte[] read=new byte[bytes.Length]; int n=0;while(n<read.Length){int got=s.Read(read,n,read.Length-n);if(got==0)throw new Exception("EOF");n+=got;}for(int i=0;i<bytes.Length;i++)if(bytes[i]!=read[i])throw new Exception("echo mismatch"); } }
 static int Main(string[] args) { try { ThreadPool.SetMinThreads(160,160); var p=new DomainPolicy("domain:example.com\nfull:exact.test\nregexp:^foo[0-9]+\\.test$\nregexp:(\ngeosite:xx\nopenai.com", "1.0.1.0/24\n1.0.2.0/23\n43.159.0.0/16\nbad"); Check(p.IsDirect("a.example.com")&&!p.IsDirect("notexample.com"),"suffix boundaries");Check(p.IsDirect("exact.test")&&!p.IsDirect("a.exact.test"),"full domain");Check(p.IsDirect("foo123.test")&&p.UnsupportedRuleCount==2,"regexp and unsupported counters");Check(p.IsDirect("1.0.1.255")&&p.IsDirect("1.0.3.255")&&!p.IsDirect("1.0.4.0"),"merged IPv4 boundaries");Check(p.IsDirect("10.20.30.40")&&p.IsDirect("192.168.2.100"),"LAN policy");Check(!p.IsDirect("api.openai.com")&&!p.IsDirect("chatgpt.com")&&!p.IsDirect("foo.oaistatic.com")&&p.IsForcedVpn("api.anthropic.com"),"VPN priority");
 http=new TcpListener(IPAddress.Loopback,0);http.Start();httpPort=((IPEndPoint)http.LocalEndpoint).Port;http.BeginAcceptTcpClient(HttpAccept,null);echo=new TcpListener(IPAddress.Loopback,0);echo.Start();echoPort=((IPEndPoint)echo.LocalEndpoint).Port;echo.BeginAcceptTcpClient(EchoAccept,null);
 using(var b=new BridgeServer(p,"testsession123")){int port=b.Start();b.Configure(0,true);string pac=Call(port,"GET /fastorange/testsession123/proxy.pac HTTP/1.1\r\nHost: 127.0.0.1\r\n\r\n");Check(pac.Contains("PROXY 127.0.0.1:"+port)&&pac.Contains("application/x-ns-proxy-autoconfig"),"PAC loopback endpoint");string rsp=Call(port,"GET http://127.0.0.1:"+httpPort+"/hello?q=1 HTTP/1.1\r\nHost: wrong\r\nProxy-Authorization: secret\r\nProxy-Connection: keep-alive\r\nConnection: keep-alive\r\n\r\n");Check(rsp.EndsWith("PASS")&&lastRequest.StartsWith("GET /hello?q=1 HTTP/1.1")&&!lastRequest.Contains("secret")&&lastRequest.Contains("Connection: close"),"HTTP rewrite and stripped proxy headers");rsp=Call(port,"POST http://127.0.0.1:"+httpPort+"/post HTTP/1.1\r\nContent-Length: 4\r\n\r\nDATA"+"GET http://evil.invalid/ HTTP/1.1\r\n\r\n");Check(rsp.EndsWith("PASS")&&lastRequest.EndsWith("DATA")&&!lastRequest.Contains("evil"),"Content-Length upload excludes pipeline");rsp=Call(port,"POST http://127.0.0.1:"+httpPort+"/chunk HTTP/1.1\r\nTransfer-Encoding: chunked\r\n\r\n4\r\nDATA\r\n0\r\nX-Test: yes\r\n\r\nGET http://evil.invalid/ HTTP/1.1\r\n\r\n");Check(rsp.EndsWith("PASS")&&lastRequest.EndsWith("X-Test: yes\r\n\r\n")&&!lastRequest.Contains("evil"),"chunked upload excludes pipeline");Tunnel(port,1);Check(true,"CONNECT opaque binary passthrough");Task[] workers=new Task[64];for(int i=0;i<workers.Length;i++){int v=i;workers[i]=Task.Factory.StartNew(delegate{Tunnel(port,v);});}Task.WaitAll(workers,15000);foreach(Task w in workers)if(!w.IsCompleted||w.IsFaulted)throw new Exception("concurrency");Check(true,"64 simultaneous CONNECT clients");long errors=b.ErrorCount;rsp=Call(port,"GET http://127.0.0.1:"+httpPort+"/denied HTTP/1.1\r\n\r\n");Check(rsp.Contains("403 Forbidden")&&b.ErrorCount==errors,"origin 403 is not network error");b.Configure(0,false);rsp=Call(port,"CONNECT no-network-test.invalid:443 HTTP/1.1\r\n\r\n");Check(rsp.Contains("503")&&b.ErrorCount==errors+1,"VPN unavailable blocks foreign request before DNS");rsp=Call(port,"CONNECT [::1]:80 HTTP/1.1\r\n\r\n");Check(rsp.Contains("400"),"IPv6 unsupported rejects safely");rsp=Call(port,"GET http://127.0.0.1:"+httpPort+"/ HTTP/1.1\r\nX: "+new string('x',33000));Check(rsp.Contains("431"),"32KB header ceiling");rsp=Call(port,"GET http://127.0.0.1:1/ HTTP/1.1\r\n\r\n");Check(rsp.Contains("502"),"connection failure returns HTTP error");string[] events=b.DrainEvents();foreach(string e in events)if(e.Contains("hello")||e.Contains("secret")||e.Contains("q=1"))throw new Exception("sensitive event");Check(events.Length<=128,"events redact paths, headers, secrets and are bounded");TcpClient open=new TcpClient("127.0.0.1",port);b.Stop();Thread.Sleep(50);Check(b.ActiveCount==0,"Stop closes all sessions");open.Close();}
 if(args.Length>0){var watch=System.Diagnostics.Stopwatch.StartNew();var real=new DomainPolicy(File.ReadAllText(args[0]),args.Length>1?File.ReadAllText(args[1]):"");watch.Stop();Check(real.RuleCount>100000&&real.RegexCount==8,"production domain list parses");Console.WriteLine("REAL rules="+real.RuleCount+" prefixes="+real.PrefixCount+" unsupported="+real.UnsupportedRuleCount+" milliseconds="+watch.ElapsedMilliseconds);}
 Console.WriteLine("ALL "+checks+" CHECKS PASSED");return 0; }catch(Exception x){Console.Error.WriteLine(x);return 1;}finally{if(http!=null)http.Stop();if(echo!=null)echo.Stop();} }
}
